'use strict';
const agents=[{id:'guardian',name:'GUARDIAN',type:'CAUTIOUS / SAFETY FIRST',symbol:'♜',desc:'Prioritizes crew and vessel safety, especially when unlikely events could cause severe harm.',bias:'May overestimate danger and favor a longer detour.',route:'Major Detour',advice:[true,true,false,true,false,true]}, {id:'pathfinder',name:'PATHFINDER',type:'BOLD / MOMENTUM FIRST',symbol:'➶',desc:'Seeks the fastest viable route, prioritizing progress and the delivery window.',bias:'May underestimate a growing storm or outdated reports.',route:'Wait 1 hour',advice:[false,false,true,false,true,false]}, {id:'analyst',name:'ANALYST',type:'ANALYTICAL / EVIDENCE FIRST',symbol:'⌘',desc:'Cross-checks forecasts and observations to balance risk against time.',bias:'Models depend on input quality. Data still needs judgment.',route:'Minor Detour',advice:[true,true,false,true,true,true]}];
const evidence=[
{title:'Storm intensifying',claim:'Gusts in the storm core have reached 48 kn and are still increasing.',source:'WX-04 Ocean Buoy · 14:28 UTC',detail:'Current time: 14:30 UTC. Buoy calibration is valid. Gusts measured 41, 45 and 48 kn at 14:22, 14:25 and 14:28. Coastal radar confirms the trend.',truth:true,why:'Direct observations from two minutes ago, corroborated by independent radar.',yes:'The strengthening trend must inform our risk assessment.',no:'Brief gusts should not disrupt our passage.'},
{title:'Eastern corridor open',claim:'A minor detour east avoids the storm core and adds an estimated 20 minutes.',source:'Coastal Radar + Route Model · 14:27 UTC',detail:'Radar shows the core moving northwest. The eastern corridor remains open, with significant wave height of 2.4 m, below our 3.5 m limit. Travel-time uncertainty: ±5 minutes.',truth:true,why:'Recent radar and vessel limits support a verifiable alternative route.',yes:'The eastern corridor offers a viable compromise.',no:'Model uncertainty makes the eastern corridor unacceptable.'},
{title:'Clear in one hour?',claim:'Hold position for one hour and the storm will clear completely.',source:'Anonymous Shipping Chat · 11:10 UTC',detail:'Posted 3 hours and 20 minutes ago, with no original forecast link. The latest marine bulletin expects at least two more hours of storm activity, moving toward the holding area.',truth:false,why:'Anonymous, outdated and contradicted by the latest bulletin. It does not justify waiting.',yes:'Waiting could avoid an unnecessary detour.',no:'Without a reliable source, this cannot justify waiting.'},
{title:'Vessel operating limit',claim:'At the current load, our significant wave height operating limit is 3.5 m.',source:'MV MERIDIAN · Signed Pre-departure Checklist',detail:'Signed for this voyage by the captain and chief engineer. The current load is accounted for. Forecast significant wave height in the core is 4.8 m, above the operating limit.',truth:true,why:'A signed record for this voyage establishes a critical operating constraint.',yes:'We should not enter waters beyond our operating limit.',no:'An experienced crew can offset the risk of exceeding the limit.'},
{title:'No cost to going wide?',claim:'A major detour west will not affect our delivery deadline.',source:'Port Schedule Cache · Yesterday, 18:00 UTC',detail:'The cache uses yesterday’s tidal window. Today’s port notice requires arrival by 16:40. Baseline ETA: 16:10. Minor detour: 16:30. Major detour: 17:05.',truth:false,why:'The cache is outdated. A major detour misses today’s deadline by 25 minutes.',yes:'The western route preserves our delivery window.',no:'We must recalculate arrival using today’s notice.'},
{title:'Holding area at risk',claim:'The storm track crosses our holding area. Staying put increases exposure.',source:'Marine Weather Bulletin 028 · 14:25 UTC',detail:'The official bulletin agrees with radar: the storm is moving northwest and will approach the holding area in 35 minutes. A one-hour hold overlaps the expected impact.',truth:true,why:'Official, recent and consistent with independent observations. Waiting is not risk-free.',yes:'We should leave the holding area before the storm arrives.',no:'Holding position is usually safer.'}];
const routes=[{name:'Wait 1 hour',cn:'Hold position for clearer weather',cost:'+60',risk:'Exposure to the moving storm',text:'Avoid an immediate maneuver, but the storm may reach the holding area.',out:'storm'}, {name:'Minor Detour',cn:'Take the eastern corridor',cost:'+20',risk:'Pass near the storm edge',text:'Use the open eastern corridor to proceed within vessel limits.',out:'balanced'}, {name:'Major Detour',cn:'Take the longer western route',cost:'+55',risk:'Risk missing the delivery window',text:'Trade extra travel time for a wider safety margin.',out:'delayed'}];
let state;let tick;let lastView='';
function reset(){clearInterval(tick);state={screen:'brief',agent:null,index:0,answers:[],verified:[],deadline:null,remaining:null,decision:null,outcome:null};render();}
function remaining(){return null;}
function updateTimer(){document.querySelectorAll('.clock').forEach(e=>e.textContent='OFF');document.querySelector('.timer')?.classList.remove('urgent');}
function start(){state.screen='situation';render();}
function finish(out){clearInterval(tick);state.outcome=out;state.screen='outcome';render();}
function guard(){return true;}
const btn=(text,action,cls='')=>`<button class="btn ${cls}" data-action="${action}">${text}</button>`;
function map(){return `<div class="panel"><div class="panel-head"><span>TACTICAL PLOT / NORTH PACIFIC</span><span class="tag amber">STORM WARNING</span></div><div class="map"><svg viewBox="0 0 780 390" role="img" aria-label="Tactical route map: vessel southwest, port northeast, central storm moving northwest; minor detour east, major detour west."><defs><pattern id="grid" width="39" height="39" patternUnits="userSpaceOnUse"><path d="M39 0H0V39" fill="none" stroke="#28434b" stroke-width=".5"/></pattern><radialGradient id="storm"><stop stop-color="#f3a75c" stop-opacity=".25"/><stop offset="1" stop-color="#ec9858" stop-opacity=".02"/></radialGradient></defs><rect width="780" height="390" fill="url(#grid)"/><path d="M0 0H130L142 23 117 41 168 53 139 82 151 112 110 135 120 151 83 172 98 205 48 235 0 229Z M780 0H665L638 31 677 51 626 70 660 109 695 102 700 137 744 160 780 155Z" fill="#1b343b" stroke="#3c5960"/><g font-family="monospace" font-size="9" fill="#5b7b85"><text x="174" y="22">32° N</text><text x="18" y="278">PACIFIC OCEAN</text><text x="580" y="374">142° E</text></g><circle cx="390" cy="185" r="120" fill="url(#storm)" stroke="#aa7548" stroke-dasharray="4 7"/><ellipse cx="390" cy="185" rx="90" ry="68" transform="rotate(-25 390 185)" fill="none" stroke="#ae8052" opacity=".55"/><ellipse cx="390" cy="185" rx="57" ry="42" transform="rotate(-25 390 185)" fill="none" stroke="#d6995c"/><path d="M368 184q38-47 54-5t-51 23q-31-16-10-45" fill="none" stroke="#e2a363" stroke-width="2"/><path d="M176 316 606 74" stroke="#677c81" stroke-dasharray="4 7" fill="none"/><path d="M176 316 260 98 432 50 606 74" stroke="#7b939c" stroke-width="2" stroke-dasharray="7 6" fill="none"/><path d="M176 316 416 314 553 217 606 74" stroke="#8ce3c3" stroke-width="2" fill="none"/><g fill="#8ce3c3"><circle cx="416" cy="314" r="4"/><circle cx="553" cy="217" r="4"/><circle cx="606" cy="74" r="5"/></g><circle cx="176" cy="316" r="22" fill="none" stroke="#8ce3c3" opacity=".35"/><path d="m176 303 9 23-9-5-9 5Z" fill="#b6f6db"/><g font-family="monospace" font-size="10"><text x="204" y="345" fill="#b6f6db">MV MERIDIAN</text><text x="617" y="61" fill="#d4e6df">PORT HELIOS</text><text x="466" y="309" fill="#8ce3c3">B / +20 MIN</text><text x="205" y="80" fill="#99adb5">C / +55 MIN</text><text x="361" y="264" fill="#e9b476">CELL 07 / 48 KN</text><text x="337" y="111" fill="#e9b476">↖ NW · 12 KN</text></g><g transform="translate(730 320)" stroke="#93b1b6" fill="none"><circle r="20"/><path d="M0-28V28M-28 0H28"/></g><text x="726" y="284" font-size="10" fill="#b3cacd">N</text></svg><div class="map-note">SIMULATED TELEMETRY · NOT FOR NAVIGATION</div></div><div class="map-legend"><span>STORM CELL</span><span>MINOR DETOUR</span><span>MAJOR DETOUR</span></div></div>`;}
function metrics(){return `<div class="metrics">${[['WIND SPEED','48','kn','↑ 7 kn / 6 min'],['WAVE HEIGHT','4.8','m','Ship limit: 3.5 m'],['VISIBILITY','1.2','nm','Reduced visibility'],['STORM VECTOR','NW','12 kn','Approaching hold area']].map(m=>`<div class="metric"><small>${m[0]}</small><strong>${m[1]} <em>${m[2]}</em></strong><p>${m[3]}</p></div>`).join('')}</div>`;}
function render(){}
document.addEventListener('click',event=>{const b=event.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;if(!guard())return;if(action==='start'&&state.screen==='brief')start();else if(action==='agents'&&state.screen==='situation'){state.screen='agents';render();}else if(action.startsWith('agent:')&&state.screen==='agents'&&state.agent===null){state.agent=Number(action.split(':')[1]);state.screen='evidence';render();}else if(action==='verify'&&state.screen==='evidence'){state.verified[state.index]=true;render();}else if(action.startsWith('answer:')&&state.screen==='evidence'){state.answers.push(action==='answer:true');state.index++;if(state.index===6)state.screen='decision';render();}else if(action.startsWith('route:')&&state.screen==='decision'){state.decision=Number(action.split(':')[1]);finish(routes[state.decision].out);}else if(action==='debrief'&&state.screen==='outcome'){state.screen='debrief';render();}else if(action==='reset'&&state.screen==='debrief')reset();});
reset();

if(document.modelContext?.registerTool){
 const lifecycle=new AbortController();
 Promise.resolve(document.modelContext.registerTool({name:'read_operation_status',description:'Read the current Storm Corridor simulation phase, advisor and completed judgments.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(input&&Object.keys(input).length)throw new Error('No parameters accepted');return {phase:state.screen,timerEnabled:false,secondsRemaining:null,advisor:state.agent===null?null:agents[state.agent].name,judgments:state.answers.slice(),outcome:state.outcome};}},{signal:lifecycle.signal})).catch(()=>{});
 window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
